import java.io.*;
import java.util.*;
import java.util.stream.Stream;

public class D5 {
    public static void main(String[] args) throws Exception {
        long[] nums = new BufferedReader(new InputStreamReader(System.in))
                .lines()
                .flatMap(line -> Arrays.stream(line.split("\\s+")))
                .filter(s -> s.matches("-?\\d+"))
                .mapToLong(Long::parseLong)
                .limit(2)
                .toArray();
        long n = nums.length > 0 ? nums[0] : 0;
        long m = nums.length > 1 ? nums[1] : 0;
        System.out.println(solve(n, m));
    }

    static long solve(long n, long m) {
        long a = Math.min(n, m), b = Math.max(n, m);
        if (a == 1) {
            long base = b / 6 * 6;
            long r = b % 6;
            if (r == 4) base += 2;
            if (r == 5) base += 4;
            return base;
        }
        return Stream.of(
                new long[]{2, 2, 0},
                new long[]{2, 3, 4},
                new long[]{2, 7, 12}
        ).filter(spec -> spec[0] == a && spec[1] == b)
                .findFirst()
                .map(spec -> spec[2])
                .orElseGet(() -> {
                    long res = a * b;
                    if (a % 2 == 1 && b % 2 == 1) res--;
                    return res;
                });
    }
}
